// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {X_WALLET, Log} from "../src/X_WALLET.sol";

contract InvMutTest is Test {
    X_WALLET c;
    function setUp() public { c = new X_WALLET(address(new Log())); }
    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        amount = bound(amount, 0, 10 ether);
        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(0);
        // A second independent Put from another actor must also succeed:
        // the lock is released after every completed call in the reference.
        address actor2 = address(uint160(uint160(actor) ^ 1));
        vm.deal(actor2, amount);
        bool ok;
        vm.prank(actor2);
        try c.Put{value: amount}(0) { ok = true; } catch { ok = false; }
        assertTrue(ok);
    }
}
